css:
.vq .wins path { fill: #ffd98a; stroke: #ffd98a; opacity: 0; transition: opacity 1.2s ease; }
.vq.t-sunset .wins path { opacity: 0.5; }
.vq.t-night .wins path { opacity: 0.95; }
.vq.t-night .wins { animation: skwin 7s ease-in-out infinite; }
@keyframes skwin { 0%, 100% { opacity: 1 } 46% { opacity: 1 } 50% { opacity: 0.72 } 56% { opacity: 1 } 80% { opacity: 0.86 } }
.vq .lit { opacity: 0.25; transition: opacity 1.2s ease; }
.vq.t-sunset .lit { opacity: 0.8; }
.vq.t-night .lit { opacity: 1; }
.vq.t-morning .lit { opacity: 0.4; }
.vq .halo { opacity: 0.35; transform-box: fill-box; transform-origin: center; animation: vqhalo 3.6s ease-in-out infinite; transition: opacity 1.2s ease; }
.vq .halo2 { animation-delay: -1.4s; }
.vq.t-sunset .halo { opacity: 0.7; }
.vq.t-night .halo { opacity: 1; }
.vq.t-morning .halo { opacity: 0.45; }
.vq .door-glow { opacity: 0; transition: opacity 1.2s ease; }
.vq.t-night .door-glow { opacity: 0.85; }
.vq.t-sunset .door-glow { opacity: 0.4; }
@keyframes vqhalo { 0%, 100% { transform: scale(0.92) } 50% { transform: scale(1.06) } }
.vq .shim { opacity: 0; animation: vqsm 5s ease-in-out infinite; }
.vq .shim2 { opacity: 0; animation: vqsm 2.8s ease-in-out infinite; }
@keyframes vqsm { 0%, 100% { opacity: 0 } 50% { opacity: 0.9 } }
.vq .flow { opacity: 0; animation: skflow 2.2s linear infinite; }
@keyframes skflow { 0% { transform: translate(0, 0); opacity: 0 } 25%, 70% { opacity: 0.85 } 100% { transform: translate(-8px, 4px); opacity: 0 } }
.vq .drop { opacity: 0; animation: skdrop 1.2s linear infinite; }
@keyframes skdrop { 0% { transform: translateY(-2px); opacity: 0 } 30% { opacity: 0.85 } 100% { transform: translateY(8px); opacity: 0 } }
.vq .mist { opacity: 0; animation: skmist 2.8s ease-out infinite; }
@keyframes skmist { 0% { transform: translate(0, 0); opacity: 0 } 40% { opacity: 0.8 } 100% { transform: translate(0, -7px); opacity: 0 } }
.vq .koi { animation: skkoi 16s ease-in-out infinite; }
.vq .koi2 { animation-duration: 22s; animation-delay: -9s; animation-direction: reverse; }
@keyframes skkoi { 0% { transform: translate(0px, 0px) } 16.7% { transform: translate(16px, 0px) } 33.3% { transform: translate(28px, 6px) } 50% { transform: translate(24px, 12px) } 66.7% { transform: translate(8px, 12px) } 83.3% { transform: translate(-4px, 6px) } 100% { transform: translate(0px, 0px) } }
.vq .pt { opacity: 0; animation: skpet 7s linear infinite; }
.vq .pt2 { animation-name: skpet2; }
@keyframes skpet { 0% { transform: translate(0, 0); opacity: 0 } 10% { opacity: 1 } 50% { transform: translate(10px, 22px) } 85% { opacity: 1 } 100% { transform: translate(14px, 46px); opacity: 0 } }
@keyframes skpet2 { 0% { transform: translate(0, 0); opacity: 0 } 10% { opacity: 1 } 45% { transform: translate(-3px, 18px) } 85% { opacity: 1 } 100% { transform: translate(8px, 42px); opacity: 0 } }
.vq .walker { animation: skwalk 30s linear infinite; }
@keyframes skwalk { 0%, 3% { transform: translate(0, 0); opacity: 0 } 6% { transform: translate(0, 0); opacity: 1 } 45%, 55% { transform: translate(76px, 38px); opacity: 1 } 94% { transform: translate(0, 0); opacity: 1 } 97%, 100% { transform: translate(0, 0); opacity: 0 } }
.vq .wbob { animation: skbob 0.56s steps(2, jump-none) infinite; }
.vq .fbob { animation: skbob 0.4s steps(2, jump-none) infinite; }
@keyframes skbob { 0%, 100% { transform: translateY(0) } 50% { transform: translateY(-1px) } }
.vq .fox { animation: skfox 18s ease-in-out infinite; }
@keyframes skfox { 0%, 10% { transform: translate(0, 0) } 40%, 60% { transform: translate(36px, 18px) } 90%, 100% { transform: translate(0, 0) } }
.vq .fxa { animation: skfa 18s steps(1) infinite; }
.vq .fxb { opacity: 0; animation: skfb 18s steps(1) infinite; }
@keyframes skfa { 0% { opacity: 1 } 50% { opacity: 0 } 100% { opacity: 0 } }
@keyframes skfb { 0% { opacity: 0 } 50% { opacity: 1 } 100% { opacity: 1 } }
.vq .birds { animation: skbird 80s linear infinite; animation-delay: -22s; }
@keyframes skbird { from { transform: translate(-40px, 0) } to { transform: translate(1160px, -36px) } }
.vq .wb { opacity: 0; animation: skfb 0.7s steps(1) infinite; }
.vq .wa { animation: skfa 0.7s steps(1) infinite; }
.vq .cf { animation: vqcl 260s linear infinite; animation-delay: -90s; }
.vq .cf2 { animation-duration: 320s; animation-delay: -200s; }
.vq .wisp { opacity: 0.92; animation: skwisp 210s linear infinite; animation-delay: -84s; }
.vq .wisp2 { animation-duration: 270s; animation-delay: -150s; }
@keyframes skwisp { from { transform: translateX(-520px) } to { transform: translateX(760px) } }
.vq.t-night .cl, .vq.t-night .cf, .vq.t-night .wisp { opacity: 0.35; }
